mapper.update:
UPDATE ticket_stock_bucket
SET
    available_stock = available_stock - #{quantity},
    locked_stock = locked_stock + #{quantity},
    version = version + 1,
    updated_at = NOW()
WHERE ticket_category_id = #{ticketCategoryId}
  AND bucket_no = #{bucketNo}
  AND available_stock >= #{quantity}

